from pathlib import Path
root=Path('.')
p=root/'TachXepTrangPDF.cs'
s=p.read_text(encoding='utf-8-sig')

def rep(old,new,label,count=1):
    global s
    if old not in s:
        raise SystemExit('v290 marker missing: '+label)
    s=s.replace(old,new,count)

# Version identity
rep('internal const string Version = "2.8.0";','internal const string Version = "2.9.0";','diag version')
rep('startup-v2.8.0.log','startup-v2.9.0.log','startup log')
rep('private const string AppVersion = "2.8.0";','private const string AppVersion = "2.9.0";','app version')

# Dirty-state tracking lives with each workspace; opening a file alone must not count as an edit.
rep('''        internal string LastError = "";\n        internal DocumentProcessingState ProcessingState = DocumentProcessingState.NotProcessed;\n''','''        internal string LastError = "";\n        internal bool HasUnsavedChanges;\n        internal DocumentProcessingState ProcessingState = DocumentProcessingState.NotProcessed;\n''','workspace dirty field')
rep('''        private Button _btnSaveOriginal;\n        private Button _btnRestoreOriginal;\n''','''        private Button _btnSaveOriginal;\n        private Button _btnSaveAllOriginal;\n        private Button _btnRestoreOriginal;\n''','save all button field')
rep('''        private string _originalBackupPath = "";\n        private readonly List<DocumentWorkspace> _documents = new List<DocumentWorkspace>();\n''','''        private string _originalBackupPath = "";\n        private bool _hasUnsavedChanges;\n        private readonly List<DocumentWorkspace> _documents = new List<DocumentWorkspace>();\n''','runtime dirty field')

# Direct toolbar button beside single-file save, same green visual group.
rep('''            _btnSaveOriginal = MakeButton("Lưu vào file gốc", 146, false); _btnSaveOriginal.Margin = new Padding(0, 0, 8, 0); _btnSaveOriginal.Click += async delegate { await ExportPdfAsync(true); }; actions.Controls.Add(_btnSaveOriginal); StyleGroupedButton(_btnSaveOriginal, UiTheme.Save);\n            _btnRestoreOriginal = MakeButton("Khôi phục PDF gốc", 154, false); _btnRestoreOriginal.Margin = new Padding(0, 0, 8, 0); _btnRestoreOriginal.Click += delegate { RestoreOriginalPdf(); }; actions.Controls.Add(_btnRestoreOriginal); StyleGroupedButton(_btnRestoreOriginal, UiTheme.Restore);\n''','''            _btnSaveOriginal = MakeButton("Lưu vào file gốc", 146, false); _btnSaveOriginal.Margin = new Padding(0, 0, 8, 0); _btnSaveOriginal.Click += async delegate { await ExportPdfAsync(true); }; actions.Controls.Add(_btnSaveOriginal); StyleGroupedButton(_btnSaveOriginal, UiTheme.Save);\n            _btnSaveAllOriginal = MakeButton("Lưu tất cả vào bản gốc", 188, false); _btnSaveAllOriginal.Margin = new Padding(0, 0, 8, 0); _btnSaveAllOriginal.Click += async delegate { await SaveAllModifiedToOriginalAsync(); }; actions.Controls.Add(_btnSaveAllOriginal); StyleGroupedButton(_btnSaveAllOriginal, UiTheme.Save);\n            _btnRestoreOriginal = MakeButton("Khôi phục PDF gốc", 154, false); _btnRestoreOriginal.Margin = new Padding(0, 0, 8, 0); _btnRestoreOriginal.Click += delegate { RestoreOriginalPdf(); }; actions.Controls.Add(_btnRestoreOriginal); StyleGroupedButton(_btnRestoreOriginal, UiTheme.Restore);\n''','toolbar save all')

# Persist/restore dirty state without treating simple file activation as an edit.
rep('''            _activeDocument.SourceWasOverwritten = _sourceWasOverwritten; _activeDocument.OriginalBackupPath = _originalBackupPath;\n            _activeDocument.ZoomPercent = _zoom == null ? 100 : _zoom.Value; _activeDocument.LastError = "";\n''','''            _activeDocument.SourceWasOverwritten = _sourceWasOverwritten; _activeDocument.OriginalBackupPath = _originalBackupPath;\n            _activeDocument.HasUnsavedChanges = _hasUnsavedChanges;\n            _activeDocument.ZoomPercent = _zoom == null ? 100 : _zoom.Value; _activeDocument.LastError = "";\n''','persist dirty')
rep('''            _sourceWasOverwritten = doc.SourceWasOverwritten; _originalBackupPath = doc.OriginalBackupPath;\n''','''            _sourceWasOverwritten = doc.SourceWasOverwritten; _originalBackupPath = doc.OriginalBackupPath; _hasUnsavedChanges = doc.HasUnsavedChanges;\n''','restore dirty')
rep('''        private void MarkActiveDocumentInProgress()\n        {\n            if (_activeDocument == null) return;\n            if (_activeDocument.ProcessingState != DocumentProcessingState.InProgress)\n            {\n                _activeDocument.ProcessingState = DocumentProcessingState.InProgress;\n                RefreshFileListItem(_activeDocument);\n            }\n        }\n''','''        private void MarkActiveDocumentInProgress()\n        {\n            if (_activeDocument == null) return;\n            _hasUnsavedChanges = true;\n            _activeDocument.HasUnsavedChanges = true;\n            if (_activeDocument.ProcessingState != DocumentProcessingState.InProgress)\n            {\n                _activeDocument.ProcessingState = DocumentProcessingState.InProgress;\n                RefreshFileListItem(_activeDocument);\n            }\n        }\n''','mark dirty on edit')

# Single-file Save Original also clears the dirty flag only after the physical replacement succeeds.
rep('''                    SetStatus("Đã lưu vào file gốc. Bản gốc an toàn: " + _originalBackupPath); _sourceWasOverwritten = true; if (_activeDocument != null) { _activeDocument.SourceWasOverwritten = true; _activeDocument.OriginalBackupPath = _originalBackupPath; }\n                    MarkActiveDocumentCompleted();\n''','''                    SetStatus("Đã lưu vào file gốc. Bản gốc an toàn: " + _originalBackupPath); _sourceWasOverwritten = true; _hasUnsavedChanges = false; if (_activeDocument != null) { _activeDocument.SourceWasOverwritten = true; _activeDocument.OriginalBackupPath = _originalBackupPath; _activeDocument.HasUnsavedChanges = false; }\n                    MarkActiveDocumentCompleted();\n''','single save clears dirty')

# Batch core: same validation/backup/rollback rules as Save Original, no per-file confirmation dialogs.
anchor='''        private SimplePdfWriter.ImagePage BuildExportPage(int i)\n'''
if anchor not in s:
    raise SystemExit('v290 marker missing: export helper anchor')
bulk='''        private async Task<string> SaveCurrentToOriginalBatchCoreAsync()\n        {\n            if (_pdf == null || _activeDocument == null || string.IsNullOrEmpty(_sourcePath)) return "Không có PDF đang hoạt động.";\n            string target = _sourcePath;\n            string tempOut = Path.Combine(Path.GetDirectoryName(target), "." + Path.GetFileName(target) + ".tachxep.tmp.pdf");\n            try\n            {\n                int exportCount = _isSplit ? _outputs.Count : _sources.Count;\n                if (exportCount <= 0) return "Tài liệu không có trang để lưu.";\n                bool lossless = CanUseLosslessFullPageExport();\n                await Task.Run(delegate\n                {\n                    if (lossless) WriteLosslessFullPagePdf(tempOut);\n                    else\n                    {\n                        SimplePdfWriter.WriteFromFactory(tempOut, exportCount, BuildExportPage, delegate(int done, int total)\n                        {\n                            try\n                            {\n                                if (done == total || done == 1 || done % 3 == 0) BeginInvoke(new Action(delegate\n                                {\n                                    _progress.Maximum = Math.Max(1, total);\n                                    _progress.Value = Math.Min(_progress.Maximum, done);\n                                    SetStatus("Đang lưu tất cả • " + Path.GetFileName(target) + ": " + done.ToString() + "/" + total.ToString());\n                                }));\n                            }\n                            catch { }\n                        });\n                    }\n                });\n                ValidateGeneratedPdf(tempOut, exportCount);\n                if (string.IsNullOrEmpty(_originalBackupPath) || !File.Exists(_originalBackupPath))\n                {\n                    string backupDir = Path.Combine(AppDiagnostics.BackupDirectory, DateTime.Now.ToString("yyyyMMdd"));\n                    Directory.CreateDirectory(backupDir);\n                    _originalBackupPath = Path.Combine(backupDir, Path.GetFileNameWithoutExtension(target) + "_original_" + DateTime.Now.ToString("HHmmss_fff") + ".pdf");\n                    string immutableOriginal = (!string.IsNullOrEmpty(_originalWorkPath) && File.Exists(_originalWorkPath)) ? _originalWorkPath : _workPath;\n                    File.Copy(immutableOriginal, _originalBackupPath, true);\n                }\n                try { File.Replace(tempOut, target, null, true); }\n                catch\n                {\n                    string old = target + ".tachxep.rollback";\n                    if (File.Exists(old)) File.Delete(old);\n                    File.Move(target, old);\n                    try { File.Move(tempOut, target); File.Delete(old); }\n                    catch { if (File.Exists(target)) File.Delete(target); if (File.Exists(old)) File.Move(old, target); throw; }\n                }\n                _sourceWasOverwritten = true; _hasUnsavedChanges = false;\n                _activeDocument.SourceWasOverwritten = true; _activeDocument.OriginalBackupPath = _originalBackupPath; _activeDocument.HasUnsavedChanges = false; _activeDocument.LastError = "";\n                MarkActiveDocumentCompleted();\n                PersistActiveDocumentState();\n                AppDiagnostics.Log("SAVE_ALL_ITEM_OK", Path.GetFileName(target));\n                return null;\n            }\n            catch (Exception ex)\n            {\n                try { if (File.Exists(tempOut)) File.Delete(tempOut); } catch { }\n                _hasUnsavedChanges = true;\n                if (_activeDocument != null)\n                {\n                    _activeDocument.HasUnsavedChanges = true; _activeDocument.ProcessingState = DocumentProcessingState.InProgress; _activeDocument.LastError = ex.Message; RefreshFileListItem(_activeDocument);\n                }\n                AppDiagnostics.LogException("SAVE_ALL_ITEM_FAIL", ex);\n                return ex.Message;\n            }\n        }\n\n        private async Task SaveAllModifiedToOriginalAsync()\n        {\n            if (_busy || _documents.Count == 0) return;\n            try { PersistActiveDocumentState(); } catch { }\n            List<DocumentWorkspace> pending = _documents.Where(delegate(DocumentWorkspace d) { return d != null && d.HasUnsavedChanges; }).ToList();\n            if (pending.Count == 0)\n            {\n                MessageBox.Show(this, "Không có PDF nào đang có thay đổi chưa lưu vào file gốc.", "Lưu tất cả vào bản gốc", MessageBoxButtons.OK, MessageBoxIcon.Information);\n                RestoreListFocus(SelectedIndex);\n                return;\n            }\n            if (MessageBox.Show(this, "Sẽ lưu " + pending.Count.ToString() + " PDF đã chỉnh sửa vào chính file gốc.\\r\\n\\r\\nMỗi file vẫn dùng cơ chế backup + kiểm tra PDF + rollback an toàn như nút Lưu vào file gốc. PDF chỉ mở/xem nhưng chưa chỉnh sửa sẽ được bỏ qua.\\r\\n\\r\\nTiếp tục?", "Lưu tất cả vào bản gốc", MessageBoxButtons.YesNo, MessageBoxIcon.Warning) != DialogResult.Yes)\n            {\n                RestoreListFocus(SelectedIndex); return;\n            }\n\n            DocumentWorkspace returnTo = _activeDocument;\n            List<string> failures = new List<string>();\n            int saved = 0;\n            SetBusy(true, "Chuẩn bị lưu tất cả PDF đã chỉnh sửa...");\n            try\n            {\n                for (int i = 0; i < pending.Count; i++)\n                {\n                    DocumentWorkspace doc = pending[i];\n                    try\n                    {\n                        if (!object.ReferenceEquals(doc, _activeDocument))\n                        {\n                            PersistActiveDocumentState();\n                            CloseActiveRuntimeForSwitch();\n                            OpenWorkspaceRuntime(doc);\n                        }\n                        SetStatus("Đang lưu tất cả: " + (i + 1).ToString() + "/" + pending.Count.ToString() + " • " + Path.GetFileName(doc.SourcePath));\n                        string error = await SaveCurrentToOriginalBatchCoreAsync();\n                        if (string.IsNullOrEmpty(error)) saved++;\n                        else failures.Add(Path.GetFileName(doc.SourcePath) + ": " + error);\n                    }\n                    catch (Exception ex)\n                    {\n                        doc.HasUnsavedChanges = true; doc.ProcessingState = DocumentProcessingState.InProgress; doc.LastError = ex.Message; RefreshFileListItem(doc);\n                        failures.Add(Path.GetFileName(doc.SourcePath) + ": " + ex.Message);\n                        AppDiagnostics.LogException("SAVE_ALL_SWITCH_OR_ITEM_FAIL", ex);\n                    }\n                }\n            }\n            finally\n            {\n                try { PersistActiveDocumentState(); } catch { }\n                if (returnTo != null && _documents.Contains(returnTo) && !object.ReferenceEquals(returnTo, _activeDocument))\n                {\n                    try { CloseActiveRuntimeForSwitch(); OpenWorkspaceRuntime(returnTo); } catch (Exception ex) { AppDiagnostics.LogException("SAVE_ALL_RETURN_FAIL", ex); }\n                }\n                SetBusy(false, null); UpdateButtons();\n            }\n\n            string summary = "Đã lưu thành công " + saved.ToString() + "/" + pending.Count.ToString() + " PDF đã chỉnh sửa vào file gốc.";\n            if (failures.Count > 0)\n            {\n                summary += "\\r\\n\\r\\nChưa lưu được " + failures.Count.ToString() + " file; các file này vẫn được giữ trong danh sách để xử lý lại:\\r\\n- " + string.Join("\\r\\n- ", failures.Take(8));\n                if (failures.Count > 8) summary += "\\r\\n- ... và " + (failures.Count - 8).ToString() + " file khác.";\n                MessageBox.Show(this, summary, "Lưu tất cả - có file chưa thành công", MessageBoxButtons.OK, MessageBoxIcon.Warning);\n            }\n            else MessageBox.Show(this, summary, "Lưu tất cả hoàn tất", MessageBoxButtons.OK, MessageBoxIcon.Information);\n        }\n\n'''
s=s.replace(anchor,bulk+anchor,1)

# Busy/button state and UI fit checks.
rep('''            _btnAuto.Enabled = !busy && _pdf != null; _btnSplit.Enabled = !busy && _pdf != null; _btnExport.Enabled = !busy && _pdf != null; _btnSaveOriginal.Enabled = !busy && _pdf != null; _btnRestoreOriginal.Enabled = !busy && _pdf != null;\n''','''            _btnAuto.Enabled = !busy && _pdf != null; _btnSplit.Enabled = !busy && _pdf != null; _btnExport.Enabled = !busy && _pdf != null; _btnSaveOriginal.Enabled = !busy && _pdf != null; if (_btnSaveAllOriginal != null) _btnSaveAllOriginal.Enabled = !busy && _documents.Any(delegate(DocumentWorkspace d) { return d.HasUnsavedChanges; }); _btnRestoreOriginal.Enabled = !busy && _pdf != null;\n''','busy save all state')
rep('''            bool has = _pdf != null; _btnUndo.Enabled = has && _undo.Count > 0; _btnRedo.Enabled = has && _redo.Count > 0; _btnAuto.Enabled = has; _btnSplit.Enabled = has && _sources.Count > 0; _btnExport.Enabled = has && (_isSplit ? _outputs.Count > 0 : _sources.Count > 0); _btnSaveOriginal.Enabled = _btnExport.Enabled; _btnRestoreOriginal.Enabled = has;\n''','''            bool has = _pdf != null; _btnUndo.Enabled = has && _undo.Count > 0; _btnRedo.Enabled = has && _redo.Count > 0; _btnAuto.Enabled = has; _btnSplit.Enabled = has && _sources.Count > 0; _btnExport.Enabled = has && (_isSplit ? _outputs.Count > 0 : _sources.Count > 0); _btnSaveOriginal.Enabled = _btnExport.Enabled; if (_btnSaveAllOriginal != null) _btnSaveAllOriginal.Enabled = !_busy && _documents.Any(delegate(DocumentWorkspace d) { return d.HasUnsavedChanges; }); _btnRestoreOriginal.Enabled = has;\n''','update save all state')

# UI smoke visible button + text fit.
rep('''                            "Lưu vào file gốc",\n                            "TỆP ĐANG XỬ LÝ",\n''','''                            "Lưu vào file gốc",\n                            "Lưu tất cả vào bản gốc",\n                            "TỆP ĐANG XỬ LÝ",\n''','ui smoke required button')
rep('''"Xuất PDF","Lưu vào file gốc","Khôi phục PDF gốc"''','''"Xuất PDF","Lưu vào file gốc","Lưu tất cả vào bản gốc","Khôi phục PDF gốc"''','ui smoke fit button')

# Extend workflow smoke: save two independently edited workspaces to their source PDFs.
batch_smoke_anchor='''                AppDiagnostics.Log("WORKFLOW_SMOKE_V270","LIST_LIFECYCLE BEGIN");\n'''
if batch_smoke_anchor not in s:
    raise SystemExit('v290 marker missing: batch smoke anchor')
batch_smoke='''                AppDiagnostics.Log("WORKFLOW_SMOKE_V290","SAVE_ALL_CORE BEGIN");\n                PersistActiveDocumentState();\n                if (!firstWorkspace.HasUnsavedChanges || !secondWorkspace.HasUnsavedChanges) throw new InvalidOperationException("Workflow smoke: edited workspaces were not marked dirty.");\n                ActivateDocument(secondWorkspace); Application.DoEvents();\n                string batchErrorSecond = await SaveCurrentToOriginalBatchCoreAsync();\n                if (!string.IsNullOrEmpty(batchErrorSecond) || secondWorkspace.HasUnsavedChanges || secondWorkspace.ProcessingState != DocumentProcessingState.Completed) throw new InvalidOperationException("Workflow smoke: batch core did not save/complete second PDF. " + batchErrorSecond);\n                PdfSession savedSecond = new PdfSession(pdfPath2); if (savedSecond.PageCount != originalSecondCount + 2) throw new InvalidOperationException("Workflow smoke: batch save did not persist merged second PDF."); savedSecond = null;\n                ActivateDocument(firstWorkspace); Application.DoEvents();\n                int expectedFirstSavedPages = _isSplit ? _outputs.Count : _sources.Count;\n                string batchErrorFirst = await SaveCurrentToOriginalBatchCoreAsync();\n                if (!string.IsNullOrEmpty(batchErrorFirst) || firstWorkspace.HasUnsavedChanges || firstWorkspace.ProcessingState != DocumentProcessingState.Completed) throw new InvalidOperationException("Workflow smoke: batch core did not save/complete first PDF. " + batchErrorFirst);\n                PdfSession savedFirst = new PdfSession(firstWorkspace.SourcePath); if (savedFirst.PageCount != expectedFirstSavedPages) throw new InvalidOperationException("Workflow smoke: batch save first PDF page count mismatch."); savedFirst = null;\n                AppDiagnostics.Log("WORKFLOW_SMOKE_V290","SAVE_ALL_CORE PASS");\n\n'''
s=s.replace(batch_smoke_anchor,batch_smoke+batch_smoke_anchor,1)

p.write_text(s,encoding='utf-8-sig')

# Portable launcher identity v2.9.0.
launcher=root/'launcher.cpp'
if launcher.exists():
    ls=launcher.read_text(encoding='utf-8-sig')
    if 'v2.8.0' not in ls: raise SystemExit('v290 launcher v2.8.0 marker missing')
    launcher.write_text(ls.replace('v2.8.0','v2.9.0'),encoding='utf-8-sig')

print('PATCH_V290_SAVE_ALL_OK')
